    for s in S:
        if s == "x":
            cnt += 1
        else:
            x_cnt.append(cnt)
            cnt = 0
    x_cnt.append(cnt)

    res = sum(abs(x-y) for x, y in zip(x_cnt, x_cnt[::-1])) // 2
