                return 0
    heightA = []
    for i in range(N-1, -1, -1):
        if i == N-1:
            heightA.append([A[i], "exact"])
        else:
            if A[i+1] < A[i]:
                heightA.append([A[i], "exact"])
            elif A[i+1] == A[i]:
                heightA.append([A[i], "bound"])
            else:
                return 0
    heightA = heightA[::-1]

    ans = 1
    for i in range(N):
        if heightT[i][1] == "exact" and heightA[i][1] == "exact":
