                return 0
        elif heightT[i][1] == "exact" and heightA[i][1] == "bound":
            if heightT[i][0] > heightA[i][0]:
                return 0
        elif heightT[i][1] == "bound" and heightA[i][1] == "exact":
            if heightT[i][0] < heightA[i][0]:
                return 0
        else:
            ans *= min(heightT[i][0], heightA[i][0])
            ans %= mod
    return ans


