class cumulative_sum:
    def __init__(self,A):
        N = len(A)
        self.S = [0]*(N+1)
        for i in range(N):
            self.S[i+1] = (self.S[i] + A[i])%K
    def get(self,i,j=None):
        if j==None:j=len(self.S)-1
        if j<=i:return 0
        return (self.S[j]-self.S[i])%K

