    for i in range(len(e)):
        for j in range(len(e[i])):
            if e[i][j] == -1:
                print(S[i][j], end="")
            else:
                print(e[i][j], end="")
        print("")

def is_end(t):
    return t[0] == h-1 and t[1] == w-1

def get_children(t):
    return ((t[0]-1,t[1]),(t[0]+1,t[1]),(t[0],t[1]-1),(t[0],t[1]+1))

def is_legal(i):
    return -1 < i[0] < h and -1 < i[1] < w and S[i[0]][i[1]] == "."

