      cnt += dfs(a[:z[0]])
      for i in range(1,len(z)):
        cnt += dfs(a[z[i-1]+1:z[i]])
      cnt += dfs(a[z[-1]+1:])
      return cnt
    else:
      a = [x-1 for x in a]
      cnt += 1

