    def __init__(self,n):
        self.par = [i for i in range(n+1)]

    def root(self,x):
        if self.par[x]==x:
            return x
        else:
            self.par[x] = self.root(self.par[x])
            return self.par[x]

    def unite(self,x,y):
        rx = self.root(x)
        ry = self.root(y)
        if rx!=ry:
            self.par[max(rx,ry)] = min(rx,ry)

    def same(self,x,y):
        rx = self.root(x)
        ry = self.root(y)
        if rx==ry:
            return True
        else:
            return False


