def ccc(start, goal, mat):
	open=queue.PriorityQueue()
	close=set()
	open.put((0, start))

	while True:
		cost, pos = open.get()
		#pa((cost,pos))
		if pos == 1:
			return cost
		if pos in close:
			continue
		for i in range(0,9+1):
			if i == pos:
				continue
			open.put((cost + mat[pos][i], i))
		else:
			close.add(pos)

	return -1

