def dfs(x):
    memo = [INF]*10
    memo[x] = 0
    hq = [(0,x)]
    heapq.heapify(hq)
    while hq:
        cost,step = heapq.heappop(hq)
        if cost > memo[step]:
            continue
        for j,c in enumerate(C[step]):
            if memo[j] > memo[step] + c:
                memo[j] = memo[step] + c
                heapq.heappush(hq,(memo[j],j))
    return memo[1]

