def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(H, W, M):
    C = Counter()
    for r in M:
        C.update(r)
    f = (H // 2) * (W // 2)
    t = (H % 2) * (W // 2) + (H // 2) * (W % 2)

    v = list(map(lambda x: -x, C.values()))
    heapq.heapify(v)
    for _ in range(f):
        c = -heapq.heappop(v)
        if c == 4:
            pass
        elif c > 4:
            c -= 4
            heapq.heappush(v, -c)
        else:
            return 'No'

    for _ in range(t):
        c = -heapq.heappop(v)
        if c == 2:
            pass
        elif c > 2:
            c -= 2
            heapq.heappush(v, -c)
        else:
            return 'No'
    return 'Yes'


