    if memo[n][idx] != 0:
        return memo[n][idx]
    if n == 1:
        if idx == k:
            return poss_of_ok_spaces(idx,True)%MOD
        elif k == idx + 1:
            return poss_of_ok_spaces(k,False)%MOD
        elif k == idx - 1:
            return poss_of_ok_spaces(idx,False)%MOD
        else:
            return 0
    ret = rc(n-1,idx)%MOD*poss_of_ok_spaces(idx,True)%MOD
