from collections import *

def dfs(x, y):
    if x==0 and y==0:
        t[x][y] = False
        return False

    if x>=1:
        t[x][y] |= not dfs(x-1, y)

    if y>=1:
        t[x][y] |= not dfs(x, y-1)

    if min(x, y)>=1:
        t[x][y] |= not dfs(x-1, y-1)

    return t[x][y]

