    A = [[]for _ in range(3)]
    for i in range(3):
        A[i] = LI()
    A_ = [[]for _ in range(3)]
    for i in range(3):
        for j in range(3):
            A_[j].append(A[i][j])
    A__ = [[]for  _ in range(2)]
    for i in range(3):
        A__[0].append(A[i][i])
        A__[1].append(A[i][2 - i])

    N = I()
    B = []
    for i in range(N):
        b = I()
        B.append(b)
        for i in range(3):
