def bfs(H, W, A, dist):
    queue = deque([])
    for h in range(H):
        A_h = A[h]
        dist_h = dist[h]
        for w in range(W):
            if A_h[w] == "#":
                dist_h[w] = 0
                queue.append((h, w))
    while queue:
        h, w = queue.popleft()
        for y, x in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            next_h, next_w = h + y, w + x
            if dist[next_h][next_w] == -1:
                dist[next_h][next_w] = dist[h][w] + 1
                queue.append((next_h, next_w))


