class Number:
    def __init__(self,number,times):
        self.number=number
        self.times=times

    def __eq__(self, other):
        if self.number==other.number:
            return True
        return False
    def __le__(self, other):
        if self.number<=other.number:
            return True
        return False
    def __lt__(self, other):
        if self.number<other.number:
            return True
        return False
    def __ge__(self, other):
        if self.number>=other.number:
            return True
        return False
    def __gt__(self, other):
        if self.number>other.number:
            return True
        return False

