def solve():
    n = II()
    ans = []
    tmp = [i for i in range(2, n + 1) if i != n - (n & 1)]
    l = 0
    r = n - 3 - (n & 1)
    for i in range(n // 2):
        ans.append(tmp[::1])
        tmp[l] -= 1
        tmp[r] += 1
        l += 1
        r -= 1
    ans += ans[::-1]
    l = []
    for i in range(1, n):
        for t in ans[i - 1]:
            if i < t:
                l.append((i, t))
    print(len(l))
