def solve(s):
    # implement process
    a,b = "",""
    cnt = 0
    # process
    for c in s:
        if a == "":
            a = c
            cnt += 1
        elif a == c:
            cnt += 1
        elif b == "":
            b = c
        elif b != c:
            return False
    return cnt == 2

def main():
    # input
    s = input()

    ans = "Yes" if solve(s) else "No"

    # output
    print(ans)
    return ans

