        if uf.same(a,b):
            B[a]+=1
            B[b]+=1

    ans=[]
    for i in range(N):
        aaa=uf.count(i)-1
        aaa-=F[i]+B[i]
        ans.append(aaa)



    print(' '.join(map(str, ans)))

