def solve():
    N, M, K = read_ints()
    disjoint_set = DisjointSet(N)
    suggestions = [-1]*N
    for _ in range(M):
        a, b = read_ints()
        a -= 1
        b -= 1
        disjoint_set.union(a, b)
        suggestions[a] -= 1
        suggestions[b] -= 1
    for _ in range(K):
        c, d = read_ints()
        c -= 1
        d -= 1
        if disjoint_set.find_parent(c) == disjoint_set.find_parent(d):
            suggestions[c] -= 1
            suggestions[d] -= 1
    return [disjoint_set.find_size(i)+suggestions[i] for i in range(N)]


