class UnionFind:
    def __init__(self, n):
        self.n = n
        self.parents = [-1 for _ in range(n)]

    def root(self, x):
        '''
        xの根を返す
        '''
        if self.parents[x] < 0:
            return x
        else:
            self.parents[x] = self.root(self.parents[x])
            return self.parents[x]

    def union(self, x, y):
        '''
        二つの木を合併する
        '''
        x = self.root(x)
        y = self.root(y)

        if x == y:
            return

        if self.parents[x] > self.parents[y]:
            x, y = y, x

        self.parents[x] += self.parents[y]
        self.parents[y] = x

    def size(self, x):
        '''
        xが属する木のサイズを返す
        '''
        return -self.parents[self.root(x)]

    def same(self, x, y):
        '''
        xとyが同じ木に属するかを調べる
        '''
        return self.root(x) == self.root(y)

    def members(self, x):
        '''
        xの木のリストを返す
        '''
        root = self.root(x)
        return [i for i in range(self.n) if self.root(i) == root]

    def roots(self):
        '''
        全ての根のリストを返す
