MOD = 10**9 + 7
def main(N, K, A):
    neg = pos = zer = 0
    for a in A:
        if a < 0: neg += 1
        elif a > 0: pos += 1
        else: zer += 1
    # print(neg, pos, zer, N - K)

    if N - K < zer:
        # ゼロになっちゃう
        return 0
    N -= zer
    A = sorted([a for a in A if a != 0], key=lambda x: abs(x))

    if (pos == 0 and K & 1) or (neg & 1 and N == K):
        # マイナスになっちゃう
