    for i in range(N):
        if Dist[i] == 10 ** 20:
            q = deque()
            q.append((i, 0))
            while q:
                nn, nd = q.popleft()
                if Dist[nn] == 10 ** 20:
                    Dist[nn] = nd
                    for ne, add in Edge[nn]: q.append((ne, nd + add))
                else:
                    if Dist[nn] == nd: continue
                    else:
                        possible = False
                        break
            if not possible:
                print("No")
                break
    else: print("Yes")

