def binary_search3(A,x):
    if x<A[0]:
        OK=0
        NG=0
    elif x>A[len(A)-1]:
        OK=len(A)-1
        NG=len(A)-1
    else:
        OK=0
        NG=len(A)
        DIV=(OK+NG)//2
        while OK+1<NG:
            if x>=A[DIV]:
                OK=DIV
            else:
                NG=DIV
            DIV=(OK+NG)//2
    return OK,NG

