    pre = 0
    ret = []
    for ci in c:
        if ci != pre:
            ret.append(ci)

        pre = ci

    return ret

def rem_alone(c: list) -> list:
    cnt = Counter(c)
    aln = set()
    for k, v in cnt.items():
        if v == 1:
            aln.add(k)

    ret = []
    for ci in c:
        if ci in aln:
            continue

        ret.append(ci)

    return ret

def find_prev_idx(c: list) -> dict:
    idx = defaultdict(list)
    prev = defaultdict(int)
    for i, ci in enumerate(c):
        prev[i+1] = idx[ci][-1] if len(idx[ci]) > 0 else -1
        idx[ci].append(i+1)


    return prev

