def length_of_sequences(l):
    length = []
    counter = 1
    for i,slime in enumerate(l):

        if i == 0:
            continue
        if l[i-1] == l[i]:
            counter += 1
        else:
            length.append(counter)
            counter = 1
        if i == len(l)-1:
            length.append(counter)

    return length



