    number_list = [i+1 for i in range(n)]
    cnt = 0
    for j in number_list:
        if j > n-2:
            break
        for k in number_list:
            if k <= j:
                continue
            l = x - j - k
            if l > n or l <= k:
                continue
            else:
                cnt += 1
    return cnt

