        #print('shogens: {}'.format(shogens))
        #print('shojikiList: {}'.format(shojikiList))
        for x,y in shogens:
            if(y==1):
                if not (x-1 in shojikiList):
                    return True
            else:
                if x-1 in shojikiList:
                    return True
    return False

