    res=[]
    while n>1:
        res.append(min_factors[n])
        n//=min_factors[n]
    return res

def factors(n):
    res=[1]
    for i,j in Counter(fast_factorization(n)).items():
        res+=[r*i**(b+1) for r in res for b in range(j)]
    return res

