    for a in range(1,max_num, 2):
        b = (a+1) // 2
        if S[a] and S[b]:
            bit.add(a, 1)

    #queryの処理

    for q in range(Q):
        l, r = MI()
        print(bit.sum(r)-bit.sum(l-1))

