    dfs2(N - 1, -1, 0)

    cnt_fen, cnt_sun = 0, 0
    for i in range(N):
        if fen_dist[i] <= sun_dist[i]:
            cnt_fen += 1
        else:
            cnt_sun += 1

    if cnt_fen <= cnt_sun:
        print('Snuke')
    else:
        print('Fennec')


