def isOK(index, H):
  now_min = index * B
  all_H = []
  for i in range(len(H)):
    if H[i] > now_min:
      all_H.append(H[i] - now_min)
  count = 0 
  for j in all_H:
    if j % (A - B) == 0:
      count += int(j // (A - B))
    else:
      count += int(j // (A - B)) + 1
  if count <= index:
    return True
  else:
    return False

