def bin_search(eval_func,left,right):
    if right-left <= 2:
        for i in range(left,right+1):
            if eval_func(i):
                return i
    mid = (left+right)//2
    if eval_func(mid):
        return bin_search(eval_func,left,mid)
    elif eval_func(right):
        return bin_search(eval_func,mid,right)

