def solve():
    def backtrack(nums, cur_state, permutations):
        if not nums:
            permutations[' '.join(cur_state)] = len(permutations)
        for i in range(len(nums)):
            cur_state.append(nums[i])
            backtrack(nums[:i]+nums[i+1:], cur_state, permutations)
            cur_state.pop()

