class Card:
    def __init__(self, s, n):
        self.suit = s
        self.num = n

class FindingMissingCards:
    def __init__(self):
        self.allCards = []
        for s in ["S","H","C","D"]:
            for n in range(1,14):
                self.allCards.append(Card(s,n))
    def find(self, cards):
        for c in cards:
