def g(X):
    """
    000
    001
    010
    011
    100
    101
    110
    111
    """
    p = 1
    i = 39
    digits = [0]*40
    N = X+1
    while i > -1:
        digits[i] = N//(2*p)*p
        if N%(2*p)-p > 0:
            digits[i] += N%(2*p)-p
        p *= 2
        i -= 1
    answer = 0
    p = 1
    for d in digits[::-1]:
        if d%2 == 1:
            answer += p
        p *= 2
    return answer


