def slv(N, K, A):
    c = Counter()
    for a in A:
        for i in range(64):
            if a & (1 << i) != 0:
                c[i] += 1

    x = 0
    for i in range(63, -1, -1):
        m = 1 << i
        if x + m > K:
            continue
        if c[i] <= N // 2:
            x += m

    return sum(map(lambda a: x ^ a, A))


