    res = 0
    for d in range(D - 1, i, -1):
        res += 2 ** d * (M[d] if b_k[d] == "0" else N - M[d])

    res += 2 ** i * M[i]

    for j in range(i):
        res += 2 ** j * (M[j] if M[j] * 2 > N else N - M[j])

    return res


