            if x_bit[j] & bl[j]:
                res2 += 2 ** j * (n - bits[j])
            else:
                res2 += 2 ** j * bits[j]

        if res2 > res1:
            for j in range(i):
                k_bit[j] |= 1
            k_bit[i] = 0
