                    if d != 0:
                        non_zero_next = non_zero + 1
                    if non_zero_next < k + 1:
                        dp[i+1][flag_less_next][non_zero_next] += dp[i][flag_less][non_zero]
    return dp[length][0][k]+dp[length][1][k]

