def solve(dice: Dice, top: str, front: str) -> None:
    # find top
    found = False
    for direction in 'SSSS':
        dice.roll(direction)
        if dice.top == top:
            found = True
            break
    if not found:
        for direction in 'EEE':
            dice.roll(direction)
            if dice.top == top:
                break

    # find front
    for _ in range(4):
        dice.rotate_right()
        if dice.front == front:
            break

    # answer right
    dice.print_right()


