import sys
# sys.setrecursionlimit(100000)


def input():
    return sys.stdin.readline().strip()


def input_int():
    return int(input())


def input_int_list():
    return [int(i) for i in input().split()]


def main():
    h, w = input_int_list()
    ans = []
    grid = []
    for _ in range(h):
        grid.append(input_int_list())
    # 行ごとに左から偶数を作っていく
    # 右端での調整は1行したに渡す
    # 計算量: O(hw)

    for i in range(h):
        for j in range(w):
            if grid[i][j] % 2 == 1:
                if i == h - 1 and j == w - 1:
                    break
                grid[i][j] -= 1
                if j < w - 1:
                    grid[i][j + 1] += 1
                    ans.append((i + 1, j + 1, i + 1, j + 2))  # 1-indexed
                elif i < h - 1:
                    grid[i + 1][j] += 1
                    ans.append((i + 1, j + 1, i + 2, j + 1))  # 1-indexed

    print(len(ans))
    for query in ans:
        print(*query)

    return


if __name__ == "__main__":
    main()

def abc109_d():
    h, w = (int(x) for x in input().split())
    grid = [[int(x) for x in input().split()] for _ in range(h)]

    move = []
    rest = []
    for i in range(h):
        pick = False
        for j in range(w):
            v = grid[i][j]
            if pick:
                if v%2:
                    pick = False
                else:
                    if j < w-1: move.append((i+1, j+1, i+1, j+2))
            else:
                if v%2:
                    pick = True
                    if j < w-1: move.append((i+1, j+1, i+1, j+2))
        rest.append(pick)

    pick = False
    for i, v in enumerate(rest):
        if pick:
            if v:
                pick = False
            else:
                if i < h-1: move.append((i+1, w, i+2, w))
        else:
            if v%2:
                pick = True
                if i < h-1: move.append((i+1, w, i+2, w))

    print(len(move))
    for mv in move:
        print(*mv, sep=' ')

