def ggg(h,w):
	a=0
	b=0
	while b < h:
		if b%2==0 and a == w-1:
			na = a
			nb = b+1
		elif b %2==0:
				na = a+1
				nb = b
		elif a == 0:
			na=a
			nb = b+1
		else:
			na = a-1
			nb = b
		yield a, b, na, nb
		a=na
		b=nb


