        ans += 2
        cnt["_A"] -= 1
        cnt["B_"] -= 1
        cnt["B_A"] -= 1
    # 残りで作る

    ans += min(sorted([cnt["_A"], cnt["B_"], cnt["B_A"]])[1:])

