    s = [input() for _ in range(N)]

    ans = 0
    cnt_a, cnt_b, cnt_ab = 0, 0, 0
    for si in s:
        ans += si.count('AB')
        if si[-1] == 'A' and si[0] == 'B':
            cnt_ab += 1
        elif si[-1] == 'A':
            cnt_a += 1
        elif si[0] == 'B':
