    dict = {}
    if target_index == None:
        for i in range(len(list)):
            dict[list[i]] = dict.get(list[i], 0) + 1
    if target_index != None:
        for i in range(len(list)):
            dict[list[i][target_index]] = dict.get(list[i][target_index], 0) + 1
    return dict

