def create_groups(n, links):
  groups = list(range(n))
  for i in range(n):
    if groups[i] != i:
      continue
    d = deque()
    d.append(i)
    while len(d) != 0:
      j = d.popleft()
      for k in links[j]:
        if groups[k] != i:
          groups[k] = i
          d.append(k)
  return groups

