class Dice:
    def __init__(self, nums):
        self.labels = {
            "1" : nums[0],
            "2" : nums[1],
            "3" : nums[2],
            "4" : nums[3],
            "5" : nums[4],
            "6" : nums[5]
        }
        self.pos = {
            "E" : "3",
            "W" : "4",
            "S" : "2",
            "N" : "5",
            "T" : "1",
            "B" : "6"
        }

    def roll(self, query):
        for q in query:
            if q == "E":
