def multiple_of_ten(number):
    while number % 10 != 0:
        number += 1
    return number


def max_difference_between_two_lst(lst1, lst2):
    difference_lst = []
    for i in range(len(lst1)):
        number1 = lst1[i]
        number2 = lst2[i]
        difference_lst.append(abs(number1 - number2))
    max_difference = max(difference_lst)
    return max_difference


