        if 0 <= xb <= 10**9 and 0 <= ya <= 10**9:
            return [l,ya,xb,l,0,0]

def cal_sub(T):
    if T == 0:
        return [0,0]
    else:
        L = int(sqrt(T))
        for l in reversed(range(1,L+1)):
            if T % l == 0:
                return [l,T//l]

