    return True

def rec(cur, s):
    if s in memo[cur]:
        return memo[cur][s]
    if cur==N:
        return 1
    ret = 0
    for c in 'AGCT':
        if ok(s+c):
            ret = (ret + rec(cur+1, s[-2:]+c))%mod
    memo[cur][s] = ret
