def counter(array):
    cnt = 0
    for i in range(Q):
        A_b = array[query[i][1] - 1]
        A_a = array[query[i][0] - 1]
        c = query[i][2]
        point = query[i][3]

        if A_b - A_a == c:
            cnt += point
    return cnt

ans = 0
# 重複組み合わせを生成
def rep_comb_pow_2(i, array):
    global ans
    if i == N:
        opt = counter(array)
        ans = max(ans, opt)
        return

    # 1スタート
    last = 1
    if len(array) > 0:
        last = array[-1]

    for j in range(last, M + 1):
        new_array = array + [j]
        rep_comb_pow_2(i + 1, new_array)

