def dfs(l,n,m,e):
    if len(l)==n:
        tmp = 0
        for aa,bb,cc,dd in zip(e[0],e[1],e[2],e[3]):
            if l[bb]-l[aa]==cc:
                tmp += dd
        global ans
        ans = max(ans,tmp)
