    self.n = n
    self.parent = [i for i in range(self.n)]
    self.rank = [0] * self.n

  def find_root(self, x):
    if self.parent[x] == x:
      return x
    else:
      self.parent[x] = self.find_root(self.parent[x])
      return self.parent[x]

