def dfs(nodes, edges, exception):
    seen = [False] * nodes
    todo = [0]
    while todo:
        node = todo.pop()
        if seen[node]:
            continue
        seen[node] = True

        for to in edges[node]:
            if (node, to) in exception:
                continue
            todo.append(to)

    return sum(seen) == nodes


