def decompose(d, n):
    limit = (int)(math.sqrt(n)) + 1
    for i in range(2, limit):
        while n % i == 0:
            if i not in d:
                d[i] = 0
            d[i] += 1
            n //= i
    if n != 1:
        if n not in d:
            d[n] = 0
        d[n] += 1

