def gcd(a, b):
    while b:
        a, b = b, a%b
    return a

def lcm(a, b):
    return a//gcd(a, b)*b

def sub(s, c, d):
    # k3*c + k4*d でsに近い値を作る
    k3 = s//c
    k4 = 0
    val = k3 * c + k4 * d
    best = val
    k4 += 1
    while k3>=0:
        val = k3 * c + k4 * d
        if val > s:
            k3 -= 1
        else:
            best = max(val, best)
            k4 += 1
    return best

