    opt = 0
    for j in range(M):
        if i == 1:
            o = query[i - 1][1] + dp_2[N - i][M - j - 1]
        elif i == N:
            o = dp_1[i - 1][j] + query[i - 1][1]
        else:
            # dp_1[i - 1][j] A[i]以前のものをj分以内に食べるナップサック
            # dp_2[N - i][M - j - 1] A[i]以降のものをM - j - 1分以内に食べるナップサック
            # dpにアクセスするだけなのでO(1)でいける
            o = dp_1[i - 1][j] + query[i - 1][1] + dp_2[N - i][M - j - 1]
        opt = max(opt, o)
