def bfs(N,start,dp):
  visited=[0]*N
  visited[start]=1
  que=deque([start])
  while que:
    a=que.popleft()
    for i in dp[a]:
      if not visited[i]:
        visited[i]=a+1
        que.append(i)
  return visited
