import sys


def solve(H: int, W: int, A: int, B: int):
    answer = [["0"]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if i < B:
                if j < A:
                    answer[i][j] = "0"
                else:
                    answer[i][j] = "1"
            else:
                if j < A:
                    answer[i][j] = "1"
                else:
                    answer[i][j] = "0"

    for i in range(H):
        print(''.join(answer[i]))                
    return


