def func(A):
    N = len(A)
    tmp = N // 2
    T = [0 for _ in range(N)]
    for i in range(0, Math.round_up(N, 2)):
        T[tmp] = A[i]
        if i % 2 == 0:
            tmp -= (i + 1) * 2
        else:
            tmp += (i + 1) * 2
    tmp = N // 2 - 1
    for i in range(0, N // 2):
        T[tmp] = A[N - i - 1]
        if i % 2 == 0:
            tmp += (i + 1) * 2
        else:
            tmp -= (i + 1) * 2
    res = 0
    for i in range(N - 1):
        res += abs(T[i + 1] - T[i])
    return res


