def ext_gcd(a, b):
    def _ext_gcd(a, b):
        xs = [1, 0]
        ys = [0, 1]
        sign = 1
        while b != 0:
            q, r = a//b, a%b
            a, b = b, r
            xtmp, ytmp = xs[1], ys[1]
            xs[1], ys[1] = q*xs[1]+xs[0], q*ys[1]+ys[0]
            xs[0], ys[0] = xtmp, ytmp
            sign = -sign
        return (a, (sign*xs[0], -sign*ys[0]))
    if a < b:
        d, (y, x) = _ext_gcd(b, a)
        return (d, (x, y))
    return _ext_gcd(a, b) 

