        def combination(self, n, r):
            if n < r:
                return 0
            if n < 0 or r < 0:
                return 0
            return self.fac[n] * (self.finv[r] * self.finv[n - r] % self.mod) % self.mod
        def combination_mul(self, N, R):
            return reduce(lambda x, y: x * self.combination(y[0], y[1]) % self.mod, zip(N, R), 1)
