def check(arr, mid, maxV):
    if arr[mid] < maxV:
        return True
    else:
        return False


def binSearch(arr, maxV):
    ok = -1
    ng = len(arr)
    while abs(ok - ng) > 1:
        mid = (ok + ng) // 2
        if check(arr, mid, maxV):
            ok = mid
        else:
            ng = mid
    return ok


