def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, A, B, C):
    A.sort()
    B.sort()
    C.sort()

    D = [0] * (N+1)
    for i in range(N-1, -1, -1):
        j = bisect.bisect_right(C, B[i])
        D[i] = D[i+1] + (N-j)

    ans = 0
    for i in range(N-1, -1, -1):
        j = bisect.bisect_right(B, A[i])
        ans += D[j]

    return ans


