    l = [int(i) for i in input().strip().split()]
    _sorted, inner = bubble_sort(l)
    _, outer = bubble_sort(_sorted + _sorted)

    print((inner * k + (k * (k - 1) // 2) * outer) % (10 ** 9 + 7))

