def solve(H, W, K, S):
    ans = 1<<60
    for s in range(1<<H-1):
        an = 0
        f = True
        mapping = np.zeros(H, dtype=np.int64)
        for i in range(H-1):
            if s>>i&1:
                an += 1
                mapping[i+1] = mapping[i]+1
            else:
                mapping[i+1] = mapping[i]
        if an >= ans:
            continue
        Cnt = np.zeros(mapping[-1]+1, dtype=np.int64)
        for x in range(W):
            for y in range(H):
                m = mapping[y]
                c = S[y, x]
                Cnt[m] += c
            if (Cnt > K).any():
                Cnt[:] = 0
                an += 1
                if an >= ans:
                    f = False
                    break
                for y in range(H):
                    m = mapping[y]
                    c = S[y, x]
                    Cnt[m] += c
                if (Cnt > K).any():
                    f = False
                    break
            if not f:
                break
        if f:
            ans = an
    return ans

