    h, w, k = getList()
    grid = []
    for i in range(h):
        grid.append(getS())

    ans = INF
    for i in range(2 ** (h-1)):
        tmp = cut(i, grid, k, h, w)
        # print(tmp)
        ans = min(ans, tmp)
    print(ans)


