def cut_chocolate(i):
    if i == 0:
        return [S]
    else:
        res = []
        pre = 0
        tmp = 0
        while i > 0:
            tmp += 1
            if i%2 == 1:
                res.append(S[pre:tmp])
                pre = tmp
            i //= 2
        res.append(S[pre:len(S)])
        return res

